sys.path.insert(0, os.path.abspath(
    os.path.join(os.path.dirname(__file__), "../../.hermes-plugin")
))

def _load():
    if "__init__" in sys.modules:
        del sys.modules["__init__"]
    return importlib.import_module("__init__")

def _bootstrap():
    m = _load()
    return m._build_bootstrap(m._skills_dir())

class TestSkillsDirResolution:
    def test_repo_layout_resolves(self):
        # The repo checkout IS the git-clone layout: .hermes-plugin/ and
        # skills/ are siblings, so resolution must succeed from here.
        m = _load()
        skills = m._skills_dir()
        assert os.path.isfile(
            os.path.join(skills, "using-superpowers", "SKILL.md")
        )

class TestBootstrapContent:
    def test_marker_and_wrapper(self):
        content = _bootstrap()
        assert BOOTSTRAP_MARKER in content
        assert content.startswith("<EXTREMELY_IMPORTANT>")
        assert content.rstrip().endswith("</EXTREMELY_IMPORTANT>")

def test_frontmatter_stripped(self):
    content = _bootstrap()
    assert "---\nname:" not in content

def test_skill_view_guidance_present(self):
    content = _bootstrap()
    assert 'skill_view("superpowers:brainstorming")' in content

def _load_plugin():
    """Re-import plugin module fresh."""
    if "__init__" in sys.modules:
        del sys.modules["__init__"]
    return importlib.import_module("__init__")

def _fire_pre_llm(ctx, **kwargs):
    hook = ctx._hooks["pre_llm_call"]
    defaults = {
        "session_id": "s1",
        "user_message": "hi",
        "conversation_history": [],
        "is_first_turn": False,
        "model": "test-model",
        "platform": "cli",
    }
    defaults.update(kwargs)
    return hook(**defaults)

class TestPluginRegistration:
    def test_register_attaches_only_pre_llm_call_hook(self, mock_ctx):
        plugin = _load_plugin()
        plugin.register(mock_ctx)
        assert list(mock_ctx._hooks.keys()) == ["pre_llm_call"]

def test_registered_skills_match_skill_directories(self, mock_ctx):
    plugin = _load_plugin()
    plugin.register(mock_ctx)
    skills_root = plugin._skills_dir()
    expected = {
        entry
        for entry in os.listdir(skills_root)
        if os.path.isfile(os.path.join(skills_root, entry, "SKILL.md"))
    }
    assert set(mock_ctx._skills.keys()) == expected

@pytest.mark.parametrize(
    "block, expected",
    [
        ('---\nname: demo\ndescription: "Quoted value."\n---\nbody', "Quoted value."),
        ("---\nname: demo\ndescription: Bare value\n---\nbody", "Bare value"),
        ("---\nname: demo\n---\nbody", ""),
        ("no frontmatter at all", ""),
    ],
)
def test_frontmatter_value_parsing(self, block, expected):
    plugin = _load_plugin()
    assert plugin._frontmatter_value(block, "description") == expected

junction() {
    local link="$1" target="$2"
    # Keep Git Bash from rewriting /J into a path.
    MSYS2_ARG_CONV_EXCL="*" cmd /c mklink /J "$link" "$target" >/dev/null
    JUNCTIONS+=("$link")
}

